const item = $input.first();
const rawContacts = typeof item.json.rawContacts === 'string' 
  ? JSON.parse(item.json.rawContacts) 
  : item.json.rawContacts;

// 1. 使用 Map 依據 Email (小寫化) 去重並合併來源
const contactMap = new Map();

for (const contact of rawContacts) {
  const normalizedEmail = (contact.email || '').trim().toLowerCase();
  if (!normalizedEmail) continue;

  if (contactMap.has(normalizedEmail)) {
    // 已存在：保留最新資料並合併來源渠道
    const existing = contactMap.get(normalizedEmail);
    const sources = new Set(existing.sources);
    sources.add(contact.source);

    contactMap.set(normalizedEmail, {
      ...existing,
      name: contact.name, // 更新為最新姓名
      phone: contact.phone || existing.phone,
      latestDate: contact.date > existing.latestDate ? contact.date : existing.latestDate,
      sources: Array.from(sources)
    });
  } else {
    // 首次出現
    contactMap.set(normalizedEmail, {
      name: contact.name,
      email: normalizedEmail,
      phone: contact.phone,
      latestDate: contact.date,
      sources: [contact.source]
    });
  }
}

const cleanContacts = Array.from(contactMap.values());

// 2. 組裝 CSV 內容 (含 UTF-8 BOM 防 Excel 亂碼)
let csvContent = "\uFEFF姓名,電子郵件,電話,最近互動日期,所有來源渠道\n";

for (const c of cleanContacts) {
  const sourcesStr = `"${c.sources.join('; ')}"`;
  csvContent += `"${c.name}","${c.email}","${c.phone}","${c.latestDate}",${sourcesStr}\n`;
}

// 3. 封裝為二進位檔案
const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(csvContent, 'utf-8'),
  'clean_contacts_export.csv',
  'text/csv'
);

return [{
  json: {
    originalCount: rawContacts.length,
    cleanCount: cleanContacts.length,
    removedDuplicates: rawContacts.length - cleanContacts.length,
    contacts: cleanContacts
  },
  binary: {
    data: binaryData
  }
}];
